SourceCode.Declaration:
/// <summary>
/// VendInvoiceInfoLine table extension
/// </summary>
[ExtensionOf(tableStr(VendInvoiceInfoLine))]
final class METVendInvoiceInfoLine_Extension
{
}

Method.Source:
    /// <summary>
    /// Check if the Purchase order is either replenishment or a fulfillment order.
    /// </summary>
    /// <returns>True if the Purchase order is either replenishment or a fulfillment order</returns>
    public boolean metIsIntercompanyOrder()
    {
        boolean     intercompanyOrder   = false;
        PurchLine   purchLine           = PurchLine::findRecId(this.PurchLineRecId);

        intercompanyOrder = PurchTable::find(this.OrigPurchId).METIntercompanyTransferReplenishment == NoYes::Yes
        || SalesTable::find(purchLine.METReplenishmentSOReference).METIntercompanyTransferFulfillment == NoYes::Yes;

        return intercompanyOrder;
    }

    public void insert(boolean _defaultRelatedTables)
    {
        next insert(_defaultRelatedTables);

        if (!this.MetClaimLine && !this.MetSystemClaimLine)
        {
            this.metUpdateReceiptData();

            if (!this.metIsIntercompanyOrder()
                && this.ReasonTableRef == 0 
                && (this.checkIfQuantityMatch(true, this.METReceiptedQuantity, this.METReceiptedCWQuantity) == LastMatchVarianceOptions::Warning))
            {
                this.metInitReasonCode(this.metGetVarianceReasonCodes(METVarianceCategory::Quantity), true);
            }

            if (this.MetPriceVarianceReasonCode == 0 && (this.PurchPrice != this.METReceiptedUnit))
            {
                this.metInitReasonCode(this.metGetVarianceReasonCodes(METVarianceCategory::Price), true);
            }
        }

        this.MetClaimLine = this.MetSystemClaimLine ? NoYes::No : this.metCheckClaimNeeded();

        this.doUpdate();
    }

    /// <summary>
    /// Creates a vendor invoice subline for EDI invoice if it does not already exist.
    /// </summary>
    public void metCreateInvoiceSubLine()
    {
        if (this.METReceiptedQuantity == 0)
        {
            if (this.vendInvoiceInfoTable().METEDIInvoice && !VendInvoiceInfoSubLine::existForLine(this.RecId))
            {
                VendInvoiceInfoSubLine subLine;
                subLine.clear();
                subLine.initFromLine(this);
                subLine.defaultRow();

                VendPackingSlipTrans trans;
                select trans where trans.InventTransId == this.InventTransId;
                subLine.initFromVendPackingSlipTrans(trans);
                subLine.insert();
                this.InventNow = subLine.InventNow;
            }
        }
    }

    private void metUpdateReceiptData()
    {
        PurchLine purchLine;
        METPurchLine metPurchLine;

        this.metCreateInvoiceSubLine();

        boolean isCW = PdsGlobal::pdsIsCWItem(this.ItemId);

        if (!isCW && this.METReceiptedQuantity == 0)
        {
            this.METReceiptedQuantity = this.purchQtyMatched();
            this.METReceiptedUnit = this.purchLine().PurchPrice;
            this.METReceiptedLineNetAmount = CurrencyExchangeHelper::amount((this.METReceiptedUnit * this.METReceiptedQuantity), this.CurrencyCode);
        }
        if (isCW)
        {
            if (this.METReceiptedRWQuantity == 0)
            {
                select firstOnly PurchPrice, ItemId, RecId from purchLine
                    where (this.InventTransId && purchLine.InventTransId == this.InventTransId)
                    || (this.PurchLineRecId && purchLine.RecId == this.PurchLineRecId)
                outer join InventItemBasePrice from metPurchLine
                    where metPurchLine.PurchLine == purchLine.RecId;

                real unitPrice = metPurchLine.InventItemBasePrice ? metPurchLine.InventItemBasePrice : purchLine.PurchPrice;

                this.METReceiptedUnit       = unitPrice;
                this.PurchPrice             = unitPrice;
                this.METReceiptedCWQuantity = this.pdsCWQtyMatched();
                this.METReceiptedRWUnit     = InventTable::find(this.ItemId).inventUnitId();
                this.METReceiptedRWQuantity = this.InventNow;
                this.METReceiptedLineNetAmount = CurrencyExchangeHelper::amount((this.METReceiptedUnit * this.METReceiptedRWQuantity), this.CurrencyCode);
                this.METInvoiceRWQuantity   = this.METInvoiceRWQuantity ? this.METInvoiceRWQuantity : this.METReceiptedRWQuantity;
                this.modifiedField(fieldNum(VendInvoiceInfoLine, METInvoiceRWQuantity));
            }
            // Update the line amount if the invoice line is a CW item and the price has been modified
            else if (this.PurchPrice)
            {
                this.modifiedField(fieldNum(VendInvoiceInfoLine, PurchPrice));
            }
        }
    }

    public void update()
    {
        boolean isCW = PdsGlobal::pdsIsCWItem(this.ItemId);

        if (!this.MetSystemClaimLine && this.METReasonCodeOverride == NoYes::No)
        {
            this.metUpdateReceiptData();

            boolean isIntercompany = this.metIsIntercompanyOrder();
            METQuantityVariance qtyVar = this.displayQuantityVariance();

            // Incident 424968: WILO - Supply - POs - Invoice Matching - Overcharge Test - Claim Invoice did not post (potentially due to 'dot' in invoice number)
            // Issue D
            // bypass this so reason code ND is not removed
            ReasonTable reasonTable;
            select firstonly RecId from reasonTable
                                      where reasonTable.METItem == this.ItemId
                                         && reasonTable.METVarianceType == METVarianceType::QuantityVarianceNoDelivery;

            if (!reasonTable)
            {
                this.ReasonTableRef = 0;
            }

            this.MetPriceVarianceReasonCode = 0;

            if (!isIntercompany
                && this.ReasonTableRef == 0 
                && !isCW
                && (this.checkIfQuantityMatch(true, this.METReceiptedQuantity, this.METReceiptedCWQuantity) == LastMatchVarianceOptions::Warning))
            {
                this.metInitReasonCode(this.metGetVarianceReasonCodes(METVarianceCategory::Quantity), true);
            }
            else if (!isIntercompany && isCW && this.ReasonTableRef == 0 && qtyVar)
            {
                METVarianceType qtyVarType = qtyVar > 0 ? METVarianceType::QuantityVarianceOver : METVarianceType::QuantityVarianceUnder;
                ReasonTable qtyReason = ReasonTable::metFindReasonCodeForVarianceType(qtyVarType);
                if (qtyReason)
                {
                    this.metInitReasonCode(qtyReason, true);
                }
            }

            if (this.MetPriceVarianceReasonCode == 0 && this.PurchPrice != this.METReceiptedUnit)
            {
                // Incident 424968: WILO - Supply - POs - Invoice Matching - Overcharge Test - Claim Invoice did not post (potentially due to 'dot' in invoice number)
                // Issue D
                // bypass this for AP-01-ND so it does not set price reason to OC                
                if (!reasonTable)
                {
                    this.metInitReasonCode(this.metGetVarianceReasonCodes(METVarianceCategory::Price), true);
                }
            }
        }

        this.MetClaimLine = this.MetSystemClaimLine ? NoYes::No : this.metCheckClaimNeeded();

        next update();
    }

    /// <summary>
    /// FieldId modified logic
    /// </summary>
    /// <param name = "_fieldId">FieldId</param>
    public void modifiedField(FieldId _fieldId)
    {
        next modifiedField(_fieldId);

        ReasonTableRef metReasonTableRef;
        ReasonTable reasonTable;

        switch(_fieldId)
        {
            case fieldNum(VendInvoiceInfoLine, ItemId):
                if (this.ItemId && !this.MetSystemClaimLine)
                {
                    ReasonTable noDelReason = this.metGetNoDeliveryReasonCode();
                    if (noDelReason.RecId)
                    {
                        this.ReasonTableRef = ReasonTableRef::createReasonTableRef(noDelReason.Reason, noDelReason.Description);
                        this.MetPriceVarianceReasonCode = 0;
                        this.MetClaimLine = noDelReason.METClaim;
                        this.MetExtCommentQty = noDelReason.MetExtComment;
                    }
                }
                break;
            case fieldNum(VendInvoiceInfoLine, ReceiveNow):
            case fieldNum(VendInvoiceInfoLine, PdsCWReceiveNow):
            case fieldNum(VendInvoiceInfoLine, PurchPrice):
            case fieldNum(VendInvoiceInfoLine, METInvoiceRWQuantity):
                boolean isCW = PdsGlobal::pdsIsCWItem(this.ItemId);
                this.METReasonCodeOverride = NoYes::No;
                if (!this.isNonPO())
                {
                    this.metFetchInitializeReasonCode();
                }

                if (isCW && !this.MetSystemClaimLine)
                {
                    this.METReceiptedLineNetAmount = CurrencyExchangeHelper::amount((this.METReceiptedRWQuantity * this.METReceiptedUnit), this.CurrencyCode);
                    this.METQuantityVariance = this.METInvoiceRWQuantity - this.METReceiptedRWQuantity;
                    this.METPriceVarianceReal = this.PurchPrice - this.METReceiptedUnit;
                    this.VendDocumentLineMap::setLineAmount(this.METInvoiceRWQuantity);
                }

                if(!isCW && !this.MetSystemClaimLine)
                {
                    this.METPriceVarianceReal   = this.displayPriceVariance();
                    this.METQuantityVariance    = this.displayQuantityVariance();
                }
                break;
            case fieldNum(VendInvoiceInfoLine, TaxItemGroup):
                this.metUpdateMarkupTransTaxItemGroup();
                break;
            case fieldNum(VendInvoiceInfoLine, ReasonTableRef):
            case fieldnum(VendInvoiceInfoLine, MetPriceVarianceReasonCode):
                this.METReasonCodeOverride = NoYes::Yes;
                break;
        }
    }

    /// <summary>
    /// Check if the invoice line should be considered for claim invoice
    /// </summary>
    /// <returns>true, if claim should be created, otherwise false</returns>
    public boolean metCheckClaimNeeded()
    {
        ReasonTable reason;
        ReasonTableRef reasonRef;
        boolean priceClaim, qtyClaim;

        select firstonly METClaim from reason
            join reasonRef
            where reasonRef.Reason == reason.Reason
            && reasonRef.RecId == this.MetPriceVarianceReasonCode;

        priceClaim = reason ? reason.METClaim : priceClaim;

        reason.clear();
        reasonRef.clear();

        select firstonly METClaim from reason
            join reasonRef
            where reasonRef.Reason == reason.Reason
            && reasonRef.RecId == this.ReasonTableRef;

        qtyClaim = reason ? reason.METClaim : qtyClaim;

        return priceClaim || qtyClaim;

    }

    /// <summary>
    /// Update TaxItemGroup
    /// </summary>
    public void metUpdateMarkupTransTaxItemGroup()
    {
        MarkupTrans         markupTrans;
        MarkupTable         markupTable;

        update_recordset markupTrans
            setting TaxItemGroup = this.TaxItemGroup
            exists join markupTable
            where markupTable.MarkupCode    == markupTrans.MarkupCode
            && markupTable.TaxItemGroup     == ''
            && markupTrans.TransTableId     == tableNum(VendInvoiceInfoLine)
            && markupTrans.TransRecId       == this.RecId
            && markupTrans.TaxItemGroup     != this.TaxItemGroup;
    }

    /// <summary>
    /// Edit method for quantity reason code
    /// </summary>
    /// <param name = "_set">booelan</param>
    /// <param name = "_reasonCode">reasoncode</param>
    /// <returns>ReasonCode</returns>
    public edit ReasonCode editReasonCode(boolean _set, ReasonCode _reasonCode)
    {
        ReasonCode metReasonCode = next editReasonCode(_set, _reasonCode);

        if(_set)
        {
            ReasonTable reasonCode = ReasonTable::find(metReasonCode);

            if (reasonCode && reasonCode.METInvoiceMatch == NoYes::No)
            {
                throw Error("@MET:InvMatchingWrongVarianceReason");
            }

            if (reasonCode.METVarianceType == METVarianceType::PriceVarianceOver
                || reasonCode.METVarianceType == METVarianceType::PriceVarianceUnder)
            {
                warning("@MET:InvMatchingInvalidQtyReason");
            }

            this.ReasonTableRef = ReasonTableRef::createReasonTableRef(reasonCode.Reason, reasonCode.Description);
            this.MetExtCommentQty = reasonCode.MetExtComment;
            this.MetClaimLine = reasonCode.METClaim;
            this.METReasonCodeOverride = NoYes::Yes;
            this.MetAutoApprove = reasonCode.METApprove;

            FormDataSource ds = this.dataSource();
            if (ds)
            {
                ds.research(true);
                ds.write();
            }
        }

        return metReasonCode;
    }

    /// <summary>
    /// Edit method for price reason code
    /// </summary>
    /// <param name = "_set">booelan</param>
    /// <param name = "_reasonCode">reasoncode</param>
    /// <returns>ReasonCode</returns>
    public edit ReasonCode editPriceReasonCode(boolean _set, ReasonCode _reasonCode)
    {
        ReasonCode metReasonCode = _reasonCode ? _reasonCode : ReasontableRef::find(this.MetPriceVarianceReasonCode).Reason;

        if (_set)
        {
            ReasonTable reasonCode = ReasonTable::find(metReasonCode);

            if (reasonCode && reasonCode.METInvoiceMatch == NoYes::No)
            {
                throw Error("@MET:InvMatchingWrongVarianceReason");
            }

            if (reasonCode.METVarianceType == METVarianceType::QuantityVarianceNoDelivery
                || reasonCode.METVarianceType == METVarianceType::QuantityVarianceOver
                || reasonCode.METVarianceType == METVarianceType::QuantityVarianceUnder)
            {
                warning("@MET:InvMatchingInvalidPriceReason");
            }

            this.MetPriceVarianceReasonCode = ReasonTableRef::createReasonTableRef(reasonCode.Reason, reasonCode.Description);
            this.MetExtComment = reasonCode.MetExtComment;
            this.MetClaimLine = reasonCode.METClaim;
            this.MetAutoApprove = reasonCode.METApprove;

            this.METReasonCodeOverride = NoYes::Yes;

            FormDataSource ds = this.dataSource();
            if (ds)
            {
                ds.write();
                ds.research(true);
            }
        }

        return metReasonCode;
    }

    /// <summary>
    /// Checks the invoice line is qunatity under / over.
    /// </summary>
    /// <returns>METVarianceType</returns>
    private METVarianceType metGetQuantityVarianceType()
    {
        if (PdsGlobal::pdsIsCWItem(this.ItemId))
        {
            return (this.METInvoiceRWQuantity > this.METReceiptedRWQuantity) ? METVarianceType::QuantityVarianceOver : METVarianceType::QuantityVarianceUnder;
        }

        return (this.ReceiveNow > this.purchQtyMatched() || this.PdsCWReceiveNow > this.pdsCWQtyMatched()) ? METVarianceType::QuantityVarianceOver : METVarianceType::QuantityVarianceUnder;
    }

/// <summary>
/// Checks the invoice line is price under / over.
/// </summary>
/// <returns>METVarianceType</returns>
private METVarianceType metGetPriceVarianceType()
{
    return this.priceVariancePercent() > 0 ? METVarianceType::PriceVarianceOver : METVarianceType::PriceVarianceUnder;
}

    /// <summary>
    /// Get the reason code for the variance type.
    /// </summary>
    /// <param name = "_varianceType">Variance type</param>
    /// <param name = "_createClaim">True/false</param>
    /// <returns>Reason code</returns>
    public ReasonTable metGetReasonCodeForIntercompanyOrder(METVarianceType _varianceType)
    {
        ReasonTable reason;

        select firstonly reason
            where reason.METVarianceType == _varianceType
            && reason.METInvoiceMatch == NoYes::Yes
            && reason.METClaim == NoYes::No;

        return reason;
    }

    /// <summary>
    /// Gets the variance reason codes for invoice line.
    /// </summary>
    /// <param name = "_varianceCategory">_varianceCategory</param>
    /// <returns>ReasonTable</returns>
    public ReasonTable metGetVarianceReasonCodes(METVarianceCategory _varianceCategory)
    {
        ReasonTable retReasonCode;
        METVarianceType varianceType;

        if (_varianceCategory == METVarianceCategory::Price)
        {
            varianceType = this.metGetPriceVarianceType();
        }
        else
        {
            varianceType = this.metGetQuantityVarianceType();
        }

        if (!this.metIsIntercompanyOrder())
        {
            retReasonCode = ReasonTable::metFindReasonCodeForVarianceType(varianceType);
        }
        else
        {
            retReasonCode = this.metGetReasonCodeForIntercompanyOrder(varianceType);
        }

        return retReasonCode;
    }

    /// <summary>
    /// Initialise reasoncode
    /// </summary>
    public void metFetchInitializeReasonCode()
    {
        if (this.ItemId && this.metGetNoDeliveryReasonCode().RecId)
        {
            return;
        }

        if (this.MetSystemClaimLine)
        {
            return;
        }

        this.MetExtComment = '';
        this.MetExtCommentQty = '';
        this.MetClaimLine =  NoYes::No;
        this.MetAutoApprove =  NoYes::No;
        this.ReasonTableRef = 0;
        this.MetPriceVarianceReasonCode = 0;

        boolean isCW = PdsGlobal::pdsIsCWItem(this.ItemId);
        PurchTable purchTable = this.purchLine().purchTable();
        boolean isIntercompany = purchTable && (purchTable.InterCompanyOrder || purchTable.InterCompanyDirectDelivery || purchTable.METIntercompanyTransferReplenishment);

        if (isCW)
        {
            // Quantity Variance for CW item
            METQuantityVariance qtyVar = this.displayQuantityVariance();
            if (qtyVar != 0)
            {
                if (isIntercompany)
                {
                    // BR-CW05 & BR-CW06: Intercompany invoice qty variance should NOT auto-assign reason code
                    this.ReasonTableRef = 0;
                }
                else
                {
                    // BR-CW01 (Invoiced > Receipted -> QuantityVarianceOver) & BR-CW02 (Invoiced < Receipted -> QuantityVarianceUnder)
                    METVarianceType qtyVarType = qtyVar > 0 ? METVarianceType::QuantityVarianceOver : METVarianceType::QuantityVarianceUnder;
                    ReasonTable qtyReason = ReasonTable::metFindReasonCodeForVarianceType(qtyVarType);
                    if (qtyReason)
                    {
                        this.metInitReasonCode(qtyReason, true);
                    }
                }
            }

            // Price Variance for CW item
            METPriceVarianceReal priceVar = this.displayPriceVariance();
            if (priceVar != 0)
            {
                if (isIntercompany && priceVar > 0)
                {
                    // BR-CW07: Intercompany price variance overcharge (Claim = No)
                    ReasonTable priceReason;
                    select firstonly priceReason
                        where priceReason.METVarianceType == METVarianceType::PriceVarianceOver
                           && priceReason.METInvoiceMatch == NoYes::Yes
                           && priceReason.METClaim == NoYes::No;
                    if (priceReason)
                    {
                        this.metInitReasonCode(priceReason, true);
                    }
                }
                else
                {
                    // BR-CW03 (Over charge) & BR-CW04 (Under charge)
                    METVarianceType priceVarType = priceVar > 0 ? METVarianceType::PriceVarianceOver : METVarianceType::PriceVarianceUnder;
                    ReasonTable priceReason = ReasonTable::metFindReasonCodeForVarianceType(priceVarType);
                    if (priceReason)
                    {
                        this.metInitReasonCode(priceReason, true);
                    }
                }
            }
        }
        else
        {
            if (this.checkIfQuantityMatch(true, this.METReceiptedQuantity, this.METReceiptedCWQuantity) == LastMatchVarianceOptions::Warning)
            {
                this.metInitReasonCode(this.metGetVarianceReasonCodes(METVarianceCategory::Quantity), true);
            }
       
            if (this.PurchPrice != this.METReceiptedUnit)
            {
                this.metInitReasonCode(this.metGetVarianceReasonCodes(METVarianceCategory::Price), true);
            }
        }
       
    }

    /// <summary>
    /// Initialise or create reasoncode
    /// </summary> 
    /// <param name = "_reasonCode">ReasonCode</param>
    /// <param name = "_create">true if new record to be created; otherwise false</param>
    public void metInitReasonCode(ReasonTable _reasonCode, boolean _create = false)
    {
        if (_reasonCode && _create)
        {
            if(_reasonCode.METVarianceType == METVarianceType::PriceVarianceOver || _reasonCode.METVarianceType == METVarianceType::PriceVarianceUnder)
            {
                this.MetPriceVarianceReasonCode = ReasonTableRef::createReasonTableRef(_reasonCode.Reason, _reasonCode.Description);
                this.MetExtComment = !this.MetExtComment ? _reasonCode.MetExtComment : this.MetExtComment;
            }
            else if(_reasonCode.METVarianceType == METVarianceType::QuantityVarianceOver || _reasonCode.METVarianceType == METVarianceType::QuantityVarianceUnder)
            {
                this.ReasonTableRef = ReasonTableRef::createReasonTableRef(_reasonCode.Reason, _reasonCode.Description);
                this.MetExtCommentQty = !this.MetExtCommentQty ? _reasonCode.MetExtComment : this.MetExtCommentQty;
            }

            this.MetClaimLine = _reasonCode.METClaim;
            this.MetAutoApprove = _reasonCode.METApprove;
        }
    }

    /// <summary>
    /// Initialise VendInvoiceInfoLine, price variance line
    /// </summary>
    /// <param name = "_vendInvoiceInfoLine">VendInvoiceInfoLine</param>
    /// <param name = "_reasonTable">ReasonTable</param>
    /// <param name = "_isCatchWeight">True if Qty failure; otherwise false</param>
    public void metInitPriceFailureMatchingLine(VendInvoiceInfoLine _vendInvoiceInfoLine, ReasonTable _reasonTable, boolean _isCatchWeight, boolean _qtyReason = false)
    {
        PurchLine               purchLine               = _vendInvoiceInfoLine.purchLine();
        InventTable             inventTable             = this.inventTable(_vendInvoiceInfoLine.ItemId);
        int                     factor;

        this.clear();
        this.initValue();

        this.ParmId                 = _vendInvoiceInfoLine.ParmId;
        this.TableRefId             = _vendInvoiceInfoLine.TableRefId;
        this.currencyCode           = _vendInvoiceInfoLine.currencyCode;
        this.AddressRefRecId        = _vendInvoiceInfoLine.AddressRefRecId;
        this.AddressRefTableId      = _vendInvoiceInfoLine.AddressRefTableId;
        this.DeliveryName           = _vendInvoiceInfoLine.DeliveryName;
        this.DeliveryPostalAddress  = _vendInvoiceInfoLine.DeliveryPostalAddress;
        this.MetTransRefId          = _vendInvoiceInfoLine.RecId;
        this.InventDimId            = _vendInvoiceInfoLine.InventDimId;
        this.OrigPurchId            = _vendInvoiceInfoLine.OrigPurchId;

        this.ItemId                 = _reasonTable.METItem;
        this.modifiedField(fieldNum(VendInvoiceInfoLine, ItemId));
        this.TaxGroup               = _vendInvoiceInfoLine.TaxGroup;
        this.TaxItemGroup           = _vendInvoiceInfoLine.TaxItemGroup;
        this.DefaultDimension       = purchLine.DefaultDimension;

        this.MetClaimLine           = _reasonTable.METClaim;
        this.MetAutoApprove         = _reasonTable.METApprove;
        
        this.METVarianceItemId      = _vendInvoiceInfoLine.ItemId;
        this.METPriceVarianceReal   = _vendInvoiceInfoLine.METPriceVarianceReal;
        this.METQuantityVariance    = _vendInvoiceInfoLine.METQuantityVariance;
        this.METIsAutoGenerated        = NoYes::Yes;
       
        //boolean qtyFailure = _reasonTable.METVarianceType == METVarianceType::QuantityVarianceOver || _reasonTable.METVarianceType == METVarianceType::QuantityVarianceUnder;

        if (_qtyReason)
        {
            this.PurchPrice         = _vendInvoiceInfoLine.PurchPrice;
            this.ReasonTableRef     = ReasonTableRef::createReasonTableRef(_reasonTable.Reason, _reasonTable.Description);
            this.MetExtCommentQty   = _vendInvoiceInfoLine.MetExtCommentQty == '' ? _reasonTable.MetExtComment : _vendInvoiceInfoLine.MetExtCommentQty;
        }
        else
        {
            this.PurchPrice                 = _isCatchWeight ? abs(_vendInvoiceInfoLine.PurchPrice - _vendInvoiceInfoLine.METReceiptedUnit): abs(_vendInvoiceInfoLine.PurchPrice - purchLine.PurchPrice);
            this.MetPriceVarianceReasonCode = ReasonTableRef::createReasonTableRef(_reasonTable.Reason, _reasonTable.Description);
            this.MetExtComment              = _vendInvoiceInfoLine.MetExtComment == '' ? _reasonTable.MetExtComment : _vendInvoiceInfoLine.MetExtComment;
        }

        this.Description = strFmt("@MET:PlaceHolder", _vendInvoiceInfoLine.VendDocumentLineMap::name(), _qtyReason ? this.MetExtCommentQty : this.MetExtComment);

        this.modifiedField(fieldNum(VendInvoiceInfoLine, PurchPrice));

        if (_qtyReason)
        {
            if (!_isCatchWeight)
            {
                this.ReceiveNow = _vendInvoiceInfoLine.ReceiveNow - _vendInvoiceInfoLine.purchQtyMatched();
            }
            else
            {
                this.ReceiveNow         = _vendInvoiceInfoLine.METInvoiceRWQuantity - _vendInvoiceInfoLine.METReceiptedRWQuantity;

            }

        }
        else
        {
            factor = _vendInvoiceInfoLine.PurchPrice > purchLine.PurchPrice ? 1 : -1;

            if(!_isCatchWeight)
            {
                this.ReceiveNow = (_vendInvoiceInfoLine.metIsPartialQty() ? _vendInvoiceInfoLine.ReceiveNow : _vendInvoiceInfoLine.purchQtyMatched()) * factor;
            }
            else
            {
                // Incident 424968: WILO - Supply - POs - Invoice Matching - Overcharge Test - Claim Invoice did not post (potentially due to 'dot' in invoice number)
                // Issue-C
                this.ReceiveNow = _vendInvoiceInfoLine.PurchPrice - _vendInvoiceInfoLine.METReceiptedUnit >= 0 ? _vendInvoiceInfoLine.METInvoiceRWQuantity : -_vendInvoiceInfoLine.METInvoiceRWQuantity;
            }
        }

        this.vendDocumentLineInterface().modifiedReceiveNowWithPromptDefault(_isCatchWeight, UnknownNoYes::Yes);
    }

    /// <summary>
    /// Reset receipted invoice line
    /// </summary>
    /// <param name = "_priceResetOnly">Only price reset</param>
    public void metResetReceiptedInvoiceLine(boolean _priceResetOnly = false)
    {
        boolean                 useCatchWeight          = this.PdsCWReceiveNow ? true : false;

        this.PurchPrice         = useCatchWeight ? this.METReceiptedUnit : this.purchLine().PurchPrice;
        this.modifiedField(fieldNum(VendInvoiceInfoLine, PurchPrice));

        if(!_priceResetOnly)
        {
            this.PdsCWReceiveNow    = this.pdsCWQtyMatched();
            this.ReceiveNow         = this.purchQtyMatched();
            this.METInvoiceRWQuantity = this.METReceiptedRWQuantity;
            this.ReasonTableRef     = 0;
            this.MetPriceVarianceReasonCode = 0;
            this.MetExtComment = '';
            this.MetExtCommentQty = '';
            this.vendDocumentLineInterface().modifiedReceiveNowWithPromptDefault(useCatchWeight, UnknownNoYes::Yes);
            this.modifiedField(fieldNum(VendInvoiceInfoLine, ReceiveNow));
        }

        if(this.validateWrite())
        {
            this.update();
        }
    }

/// <summary>
/// Checks if invoice quantity is less than product receipt quantity matched. 
/// </summary>
/// <returns>True if quantities are equal; otherwise false</returns>
public boolean metIsPartialQty()
{
    return this.ReceiveNow < this.purchQtyMatched();
}

/// <summary>
/// Checks if CW invoice quantity is less than product receipt quantity matched.
/// </summary>
/// <returns>True if quantities are equal; otherwise false</returns>
public boolean metCWIsPartialQty()
{
    return this.PdsCWReceiveNow < this.pdsCWQtyMatched();
}

    /// <summary>
    /// Returns the quantity variance.
    /// </summary>
    /// <returns>METQuantityVariance</returns>
    public display METQuantityVariance displayQuantityVariance()
    {
        if (PdsGlobal::pdsIsCWItem(this.ItemId))
        {
            return this.METInvoiceRWQuantity - this.METReceiptedRWQuantity;
        }

        return this.ReceiveNow - this.METReceiptedQuantity;
    }

    /// <summary>
    /// Returns the price variance.
    /// </summary>
    /// <returns>METPriceVarianceReal</returns>
    public display METPriceVarianceReal displayPriceVariance()
    {
        ReasonTable reason;
        ReasonTableRef reasonTableRef;

        if (this.ReasonTableRef)
        {
            select firstonly Reason, METClaim, METVarianceType from reason
                exists join reasonTableRef
                where reasonTableRef.Reason == reason.Reason
                    && reasonTableRef.RecId == this.ReasonTableRef;

            if (reason.METVarianceType == METVarianceType::QuantityVarianceNoDelivery)
            {
                return 0.0;
            }
        }

        return this.PurchPrice - this.METReceiptedUnit;
    }

    /// <summary>
    /// CB411_412_ChargeThrough
    /// </summary>
    /// <param name = "_cbCTInvoiceLine"><c>METCBCTInvoiceLine</c> record to initialise fields from</param>
    void METInitFromCBCTInvoiceLine(METCBCTInvoiceLine _cbCTInvoiceLine)
    {
        this.Description        = _cbCTInvoiceLine.Description;
        this.ItemId             = _cbCTInvoiceLine.ItemId;
        this.ReceiveNow         = _cbCTInvoiceLine.Qty;
        this.PurchPrice         = _cbCTInvoiceLine.Amount;
        this.TaxGroup           = _cbCTInvoiceLine.TaxGroup;
        this.TaxItemGroup       = _cbCTInvoiceLine.TaxItemGroup;
        this.DefaultDimension   = _cbCTInvoiceLine.FinancialDimension;

        InventDim inventDim;
        inventDim.InventSiteId  = _cbCTInvoiceLine.InventSiteId;
        inventDim.InventLocationId = _cbCTInvoiceLine.InventLocationId;
        inventDim = InventDim::findOrCreate(inventDim);
        this.InventDimId        = inventDim.inventDimId;
    }

    /// <summary>
    /// Bug 275352: CB411- Vendor auto charges not getting copied to sales lines (DIsc1 and Disc2) if created through CT
    /// </summary>
    /// <returns>True if an off remittance charge code exists for the <c>VendInvoiceInfoLine</c> record</returns>
    public boolean METExistOffRemittanceChargeCode()
    {
        MarkupTrans markupTrans;
        MarkupTable markupTable;

        select firstonly RecId from markupTrans
            where markupTrans.TransTableId == tableNum(VendInvoiceInfoLine)
               && markupTrans.TransRecId   == this.RecId
            exists join markupTable
            where markupTable.MarkupCode == markupTrans.MarkupCode
               && markupTable.METIsOffRemittance;

        return markupTrans.RecId;
    }

/// <summary>
/// Checks if this line is associated with a No Delivery variance reason.
/// </summary>
/// <returns>The ReasonTable record if associated, otherwise an empty record.</returns>
public ReasonTable metGetNoDeliveryReasonCode()
{
    ReasonTable reasonCode;
    if (this.ItemId)
    {
        select firstonly reasonCode
        where reasonCode.METItem == this.ItemId
           && reasonCode.METVarianceType == METVarianceType::QuantityVarianceNoDelivery;
    }
    return reasonCode;
}

    /// <summary>
    /// Validates the reason code.
    /// </summary>
    public boolean metValidateReasonCode()
    {
        ReasonTable reasonCode;
        ReasonTableRef reasonRef;
        boolean ret = true;

        if (this.ItemId)
        {
            select firstonly reasonCode
                join reasonRef
            where reasonRef.Reason == reasonCode.Reason
                && (reasonRef.RecId == this.ReasonTableRef || reasonRef.RecId == this.MetPriceVarianceReasonCode)
                && reasonCode.METItem != this.ItemId
                && reasonCode.METVarianceType == METVarianceType::QuantityVarianceNoDelivery;

            if (reasonCode.RecId)
            {
                ret = checkFailed("@MET:InvalidReasonCodeVal");
            }
        }

        return ret;
    }

    /// <summary>
    /// Checks if the pending vendor invoice line is eligible for No Delivery processing.
    /// </summary>
    /// <returns>True if eligible, otherwise false.</returns>
    public boolean metIsEligibleForNoDelivery()
    {
        VendInvoiceInfoTable header = this.vendInvoiceInfoTable();

        if (!header)
        {
            select firstonly header
            where header.TableRefId == this.TableRefId
               && header.ParmId == this.ParmId;
        }

        if (!header 
            || !header.PurchId 
            || header.METChargeThrough == NoYes::Yes
            || header.METCrossDock == NoYes::Yes
            || header.METRDA == NoYes::Yes
            || header.isLandedCostEnabled())
        {
            return false;
        }

        PurchTable purchTable = this.purchLine().purchTable();
        if (purchTable 
            && (purchTable.InterCompanyOrder 
            || purchTable.InterCompanyDirectDelivery 
            || purchTable.METIntercompanyTransferReplenishment
            || purchTable.InterCompanyCustPurchOrderFormNum))
        {
            return false;
        }

        return true;
    }

    /// <summary>
    /// Validates if the quantity and price are positive when the reason code has METPositiveOnly checked.
    /// </summary>
    /// <param name = "_showError">Boolean to show standard checkFailed</param>
    /// <returns>True if valid, otherwise false</returns>
    public boolean metValidatePositiveOnly(boolean _showError = true)
    {
        boolean ret = true;
        ReasonTable reasonCode;
        ReasonTableRef reasonRef;

        if (this.ReasonTableRef)
        {
            select firstonly METVarianceType from reasonCode
            join reasonRef
            where reasonRef.Reason == reasonCode.Reason
               && reasonRef.RecId == this.ReasonTableRef;
        
            if (reasonCode.METVarianceType == METVarianceType::QuantityVarianceNoDelivery && (this.ReceiveNow < 0 || this.PurchPrice < 0 || this.LineAmount < 0))
            {
                ret = _showError ? checkFailed("@MET:NegativeValuesNotAllowed") : false;
            }
        }

        return ret;
    }

    /// <summary>
    /// Validates the record before writing.
    /// </summary>
    /// <returns>Boolean indicating validation success</returns>
    public boolean validateWrite()
    {
        boolean ret = next validateWrite();

        if (ret && !this.MetSystemClaimLine)
        {
            ret = this.metValidatePositiveOnly(true);
        }

        if (ret)
        {
            ret = this.metValidateReasonCode();
        }

        return ret;
    }

    /// <summary>
    /// Validates field values.
    /// </summary>
    /// <param name = "_fieldId">Field ID to validate</param>
    /// <param name = "_purchLine">Associated purchase line record; optional</param>
    /// <returns>True if validation is successful; otherwise, false</returns>
    public boolean validateField(FieldId _fieldId, PurchLine _purchLine)
    {
        boolean ret = next validateField(_fieldId, _purchLine);

        if (ret)
        {
            if (_fieldId == fieldNum(VendInvoiceInfoLine, ItemId))
            {
                ReasonTable reasonCode = this.metGetNoDeliveryReasonCode();
                if (reasonCode.RecId)
                {
                    if (!this.metIsEligibleForNoDelivery())
                    {
                        ret = checkFailed("@MET:NoDeliveryServiceItemNotAllowed");
                    }
                }
            }
            else if (_fieldId == fieldNum(VendInvoiceInfoLine, ReceiveNow)
             || _fieldId == fieldNum(VendInvoiceInfoLine, PurchPrice)
             || _fieldId == fieldNum(VendInvoiceInfoLine, LineAmount))
            {
                ret = this.metValidatePositiveOnly(true);
            }
        }

        return ret;
    }
